import 'package:pocketbase_drift/pocketbase_drift.dart';

final client = $PocketBase.database('http://127.0.0.1:8090');

// Watch a collection reactively
final stream = client.watchRecordsState('posts');
stream.listen((state) {
  if (state.hasError) {
    print('Error: ${state.error}');
  } else {
    print('Fetched ${state.data?.length} posts');
  }
});
